-- Synthetic seed for the medium-measured fixture, generated by scripts/generate-fixtures.mjs (postgresql).
-- Do not edit by hand: run "npm run fixtures" to regenerate.
-- Tables whose declared rowCount exceeds 200 receive exactly 200 rows; tables without a
-- measurement receive 10; rowCount 0 receives none. Counts above 200 are declared in the
-- JSON snapshot, not measured from this seed (see fixtures/README.md).
BEGIN;

CREATE SCHEMA IF NOT EXISTS "analytics";
CREATE SCHEMA IF NOT EXISTS "billing";
CREATE SCHEMA IF NOT EXISTS "catalog";
CREATE SCHEMA IF NOT EXISTS "fulfillment";
CREATE SCHEMA IF NOT EXISTS "identity";
CREATE SCHEMA IF NOT EXISTS "ordering";
CREATE SCHEMA IF NOT EXISTS "platform";
CREATE SCHEMA IF NOT EXISTS "support";

CREATE TABLE "identity"."tenants" (
  "id" integer NOT NULL,
  "name" varchar(200) NOT NULL,
  "metadata" jsonb NOT NULL,
  "error_code" varchar(32) NOT NULL,
  "phone" varchar(32),
  "latitude" numeric(9,6),
  "updated_by" integer,
  "line2" varchar(255) NOT NULL,
  "description" text,
  "byte_size" bigint NOT NULL,
  "starts_at" timestamp,
  "threshold" numeric(10,2),
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  CONSTRAINT "pk_tenants" PRIMARY KEY ("id"),
  CONSTRAINT "uq_tenants_name" UNIQUE ("name")
);

CREATE TABLE "identity"."users" (
  "id" integer NOT NULL,
  "name" varchar(200) NOT NULL,
  "title" varchar(255) NOT NULL,
  "country_code" varchar(2),
  "batch_id" varchar(64) NOT NULL,
  "summary" text NOT NULL,
  "url" varchar(2048),
  "due_at" timestamp NOT NULL,
  "starts_at" timestamp,
  "file_name" varchar(255),
  "row_version" integer NOT NULL,
  "phone" varchar(32) NOT NULL,
  "latitude" numeric(9,6),
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "tenant_id" integer NOT NULL,
  CONSTRAINT "pk_users" PRIMARY KEY ("id"),
  CONSTRAINT "uq_users_name" UNIQUE ("name"),
  CONSTRAINT "fk_users_tenant_id" FOREIGN KEY ("tenant_id") REFERENCES "identity"."tenants" ("id")
);
CREATE INDEX "ix_users_tenant_id" ON "identity"."users" ("tenant_id");

CREATE TABLE "identity"."roles" (
