  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "tenant_id" integer,
  CONSTRAINT "pk_sessions" PRIMARY KEY ("id"),
  CONSTRAINT "fk_sessions_tenant_id" FOREIGN KEY ("tenant_id") REFERENCES "identity"."tenants" ("id")
);
CREATE INDEX "ix_sessions_created_at" ON "identity"."sessions" ("created_at");
CREATE INDEX "ix_sessions_tenant_id" ON "identity"."sessions" ("tenant_id");

CREATE TABLE "identity"."invitations" (
  "id" bigint NOT NULL,
  "approved_at" timestamp,
