  "updated_at" timestamp NOT NULL,
  "user_id" integer,
  "session_id" bigint,
  CONSTRAINT "pk_invitations" PRIMARY KEY ("id"),
  CONSTRAINT "ck_invitations_rating" CHECK (rating >= 0 AND rating <= 5),
  CONSTRAINT "fk_invitations_user_id" FOREIGN KEY ("user_id") REFERENCES "identity"."users" ("id"),
  CONSTRAINT "fk_invitations_session_id" FOREIGN KEY ("session_id") REFERENCES "identity"."sessions" ("id")
);
